    /// `EC.ExitStatus.errorConstantToExitStatus`.
    pub const fn exit_status(self) -> ExitStatus {
        match self {
            Ec::CFG_ERROR_READING_FILE => ExitStatus::ErrorConfigParse,
            Ec::CFG_EXPECTED_SYMBOL => ExitStatus::ErrorConfigParse,
            Ec::CFG_EXPECT_ID => ExitStatus::ErrorConfigParse,
            Ec::CFG_GENERAL => ExitStatus::ErrorConfigParse,
            Ec::CFG_LEXICAL_ERROR => ExitStatus::ErrorConfigParse,
            Ec::CFG_MISSING_ID => ExitStatus::ErrorConfigParse,
            Ec::CFG_TWICE_KEYWORD => ExitStatus::ErrorConfigParse,
            Ec::NO_ERROR => ExitStatus::Success,
            Ec::TLC_ACTION_PROPERTY_EVALUATION_FAILED => ExitStatus::ViolationLiveness,
            Ec::TLC_ACTION_PROPERTY_VIOLATED_BEHAVIOR => ExitStatus::ViolationLiveness,
            Ec::TLC_ASSUMPTION_EVALUATION_ERROR => ExitStatus::ViolationAssumption,
            Ec::TLC_ASSUMPTION_FALSE => ExitStatus::ViolationAssumption,
            Ec::TLC_CANT_HANDLE_CONJUNCT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CANT_HANDLE_REAL_NUMBERS => ExitStatus::ErrorConfigParse,
            Ec::TLC_CANT_HANDLE_SUBSCRIPT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CANT_HANDLE_TOO_MANY_NEXT_STATE_RELS => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_ID_DOES_NOT_APPEAR_IN_SPEC => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_ID_HAS_VALUE => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_ID_MUST_NOT_BE_CONSTANT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_ID_REQUIRES_NO_ARG => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_MISSING_INIT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_MISSING_NEXT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_NOT_BOTH_SPEC_AND_INIT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_NO_STATE_TYPE => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_OP_ARITY_INCONSISTENT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_OP_IS_EQUAL => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_OP_NOT_IN_SPEC => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_OP_NO_ARGS => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_PROPERTY_ACTION_LEVEL => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_PROPERTY_ACTION_LEVEL_ANGLE_A_SUB_V => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_PROPERTY_ACTION_LEVEL_SQUARE_A_SUB_V => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_PROPERTY_NOT_CORRECTLY_DEFINED => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_RHS_ID_APPEARED_AFTER_LHS_ID => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_SPECIFIED_NOT_DEFINED => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_SPEC_IS_TRIVIAL => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_SUBSTITUTION_NON_CONSTANT => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_UNDEFINED_OR_NO_OPERATOR => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_VALUE_NOT_ASSIGNED_TO_CONSTANT_PARAM => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_WRONG_SUBSTITUTION => ExitStatus::ErrorConfigParse,
            Ec::TLC_CONFIG_WRONG_SUBSTITUTION_NUMBER_OF_ARGS => ExitStatus::ErrorConfigParse,
            Ec::TLC_DEADLOCK_REACHED => ExitStatus::ViolationDeadlock,
            Ec::TLC_FINGERPRINT_EXCEPTION => ExitStatus::FailureSpecEval,
            Ec::TLC_INVARIANT_EVALUATION_FAILED => ExitStatus::FailureSafetyEval,
            Ec::TLC_INVARIANT_VIOLATED_BEHAVIOR => ExitStatus::ViolationSafety,
            Ec::TLC_INVARIANT_VIOLATED_INITIAL => ExitStatus::ViolationSafety,
            Ec::TLC_INVARIANT_VIOLATED_LEVEL => ExitStatus::FailureSafetyEval,
            Ec::TLC_LIVE_FORMULA_TAUTOLOGY => ExitStatus::FailureLivenessEval,
            Ec::TLC_NESTED_EXPRESSION => ExitStatus::FailureSpecEval,
            Ec::TLC_NO_MODULES => ExitStatus::ErrorConfigParse,
            Ec::TLC_PARSING_FAILED => ExitStatus::ErrorSpecParse,
            Ec::TLC_PARSING_FAILED2 => ExitStatus::ErrorSpecParse,
            Ec::TLC_POSSIBLE_UNWITNESSED => ExitStatus::ViolationAssumption,
            Ec::TLC_POSTCONDITION_EVALUATION_ERROR => ExitStatus::ViolationAssumption,
            Ec::TLC_POSTCONDITION_FALSE => ExitStatus::ViolationAssumption,
            Ec::TLC_PROPERTY_VIOLATED_INITIAL => ExitStatus::ViolationLiveness,
            Ec::TLC_STATES_AND_NO_NEXT_ACTION => ExitStatus::FailureSpecEval,
            Ec::TLC_STATE_NOT_COMPLETELY_SPECIFIED_NEXT => ExitStatus::FailureSpecEval,
            Ec::TLC_TEMPORAL_PROPERTY_VIOLATED => ExitStatus::ViolationLiveness,
            Ec::TLC_VALUE_ASSERT_FAILED => ExitStatus::ViolationAssert,
            _ => ExitStatus::Error,
        }
    }

